import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    records = []

    for record in reader:
        if not record or all(value == "" for value in record):
            continue
        if len(record) == 1 and record[0].lstrip().startswith("#"):
            continue
        records.append(record)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    width = len(columns)
    rows = []

    for record in records[1:]:
        if len(record) < width:
            record = record + [""] * (width - len(record))
        elif len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
